	iter := commit
	for len(iter.ParentHashes) > 0 {
		parent, parentErr := s.repo.CommitObject(iter.ParentHashes[0])
		if parentErr != nil {
			break
		}
		iter = parent
	}
	oldest := iter.Committer.When.UTC()

	return GenerationMetadata{
		OldestCheckpointAt: oldest,
		NewestCheckpointAt: newest,
	}
