// sessionPhaseLabel returns the display status for a session.
func sessionPhaseLabel(s *strategy.SessionState) string {
	if s.EndedAt != nil {
		return "ended"
	}
	status := string(s.Phase)
	if status == "" {
		return "idle"
	}
