+func loadRemoteV2Snapshot(ctx context.Context, runner CommandRunner, repoDir string, limit int) (*remoteV2Snapshot, []string, error) {
+	settings, err := readEntireSettings(repoDir)
+	if err != nil {
+		return nil, nil, err
+	}
+	remoteURL, err := settings.CheckpointRemoteFetchURL()
+	if err != nil {
+		return nil, nil, err
+	}
+
+	tmpDir, err := os.MkdirTemp("", "entire-brain-v2-*")
+	if err != nil {
+		return nil, nil, fmt.Errorf("create remote v2 temp repo: %w", err)
+	}
+	cleanupOnError := true
+	defer func() {
+		if cleanupOnError {
+			os.RemoveAll(tmpDir)
+		}
+	}()
+
+	if _, stderr, err := runner.Run(ctx, tmpDir, "git", "init", "-q"); err != nil {
+		return nil, warningLines("git init", stderr), fmt.Errorf("initialize remote v2 temp repo: %w", err)
+	}
+
+	refspec := "+" + v2MainRef + ":" + v2MainRef
+	if _, stderr, err := runner.Run(ctx, tmpDir, "git", "fetch", "--no-tags", "--depth=1", remoteURL, refspec); err != nil {
+		warnings := warningLines("remote v2 fetch", stderr)
+		return nil, warnings, fmt.Errorf("fetch remote v2 main: %w", err)
+	}
+
+	archivePath := filepath.Join(tmpDir, "v2-main.tar")
+	if _, stderr, err := runner.Run(ctx, tmpDir, "git", "archive", "--format=tar", "--output", archivePath, v2MainRef); err != nil {
+		warnings := warningLines("remote v2 archive", stderr)
+		return nil, warnings, fmt.Errorf("archive remote v2 main: %w", err)
+	}
+
+	selected, checkpointCount, warnings, err := readRemoteV2MetadataArchive(archivePath, limit)
+	if err != nil {
+		return nil, warnings, err
+	}
+	if len(selected) == 0 {
+		return nil, warnings, errors.New("remote v2 main contained no sessions")
+	}
+
+	cleanupOnError = false
+	warnings = append(warnings, "exporting compact transcripts directly from configured checkpoint remote v2 main")
+	return &remoteV2Snapshot{
+		TempDir:         tmpDir,
+		Ref:             v2MainRef,
+		Selected:        selected,
+		CheckpointCount: checkpointCount,
+	}, warnings, nil
+}
+
+func readRemoteV2MetadataArchive(archivePath string, limit int) (map[string]selectedSession, int, []string, error) {
+	f, err := os.Open(archivePath)
+	if err != nil {
+		return nil, 0, nil, fmt.Errorf("open remote v2 archive: %w", err)
+	}
+	defer f.Close()
+
+	type metadataFile struct {
+		checkpointID string
+		sessionIndex int
+		data         []byte
+	}
+
+	checkpointIDs := make(map[string]struct{})
+	var metadataFiles []metadataFile
+	var warnings []string
+
+	tr := tar.NewReader(f)
+	for {
+		header, err := tr.Next()
+		if errors.Is(err, io.EOF) {
+			break
+		}
+		if err != nil {
+			return nil, 0, warnings, fmt.Errorf("read remote v2 archive: %w", err)
+		}
+		if header.Typeflag != tar.TypeReg {
+			continue
+		}
+
+		path := filepath.ToSlash(header.Name)
+		if checkpointID, ok := checkpointIDFromRootMetadataPath(path); ok {
+			checkpointIDs[checkpointID] = struct{}{}
+			continue
+		}
+
+		checkpointID, sessionIndex, ok := sessionMetadataPathParts(path)
+		if !ok {
+			continue
+		}
+		data, err := io.ReadAll(tr)
+		if err != nil {
+			return nil, 0, warnings, fmt.Errorf("read %s from remote v2 archive: %w", path, err)
+		}
+		checkpointIDs[checkpointID] = struct{}{}
+		metadataFiles = append(metadataFiles, metadataFile{
+			checkpointID: checkpointID,
+			sessionIndex: sessionIndex,
+			data:         data,
+		})
+	}
+
+	allowed := limitedCheckpointSet(checkpointIDs, limit)
+	selected := make(map[string]selectedSession)
+	for _, file := range metadataFiles {
+		if _, ok := allowed[file.checkpointID]; !ok {
+			continue
+		}
+
+		var meta checkpointExportSession
+		if err := json.Unmarshal(file.data, &meta); err != nil {
+			warnings = append(warnings, fmt.Sprintf("skipped checkpoint %s session %d: parse metadata: %v", file.checkpointID, file.sessionIndex, err))
+			continue
+		}
+		if meta.SessionID == "" {
+			warnings = append(warnings, fmt.Sprintf("skipped checkpoint %s session %d: missing session_id", file.checkpointID, file.sessionIndex))
+			continue
+		}
+
+		var createdAt time.Time
+		if meta.CreatedAt != nil {
+			createdAt = *meta.CreatedAt
+		}
+		candidate := selectedSession{
+			CheckpointID:     file.checkpointID,
+			SessionIndex:     file.sessionIndex,
+			SessionID:        meta.SessionID,
+			Agent:            meta.Agent,
+			Model:            meta.Model,
+			Kind:             meta.Kind,
+			ReviewSkills:     meta.ReviewSkills,
+			CreatedAt:        createdAt,
+			TurnID:           meta.TurnID,
+			IsTask:           meta.IsTask,
+			ToolUseID:        meta.ToolUseID,
+			FilesTouched:     meta.FilesTouched,
+			TokenUsage:       meta.TokenUsage,
+			Summary:          meta.Summary,
+			CheckpointsCount: meta.CheckpointsCount,
+		}
+
+		current, ok := selected[meta.SessionID]
+		if !ok || shouldReplaceSession(current, candidate) {
+			selected[meta.SessionID] = candidate
+		}
+	}
+
+	if len(checkpointIDs) > limit {
+		warnings = append(warnings, fmt.Sprintf("checkpoint ref discovery capped at %d checkpoints; rerun with --checkpoint-limit <N> to inspect more", limit))
+	}
+	return selected, min(len(checkpointIDs), limit), warnings, nil
+}
+
+func limitedCheckpointSet(ids map[string]struct{}, limit int) map[string]struct{} {
+	sorted := make([]string, 0, len(ids))
+	for id := range ids {
+		sorted = append(sorted, id)
+	}
+	sort.Strings(sorted)
+	if len(sorted) > limit {
+		sorted = sorted[:limit]
+	}
+	allowed := make(map[string]struct{}, len(sorted))
+	for _, id := range sorted {
+		allowed[id] = struct{}{}
+	}
+	return allowed
+}
+
+func checkpointIDFromRootMetadataPath(path string) (string, bool) {
+	parts := strings.Split(path, "/")
+	if len(parts) != 3 || parts[2] != "metadata.json" {
+		return "", false
+	}
+	checkpointID := parts[0] + parts[1]
+	return checkpointID, isCheckpointID(checkpointID)
+}
+
+func sessionMetadataPathParts(path string) (string, int, bool) {
+	parts := strings.Split(path, "/")
+	if len(parts) != 4 || parts[3] != "metadata.json" {
+		return "", 0, false
+	}
+	checkpointID := parts[0] + parts[1]
+	if !isCheckpointID(checkpointID) {
+		return "", 0, false
+	}
+	sessionIndex, err := strconv.Atoi(parts[2])
+	if err != nil || sessionIndex < 0 {
+		return "", 0, false
+	}
+	return checkpointID, sessionIndex, true
+}
