func treePathSet(data []byte) map[string]struct{} {
	paths := make(map[string]struct{})
	for _, line := range strings.Split(string(data), "\n") {
		path := strings.TrimSpace(filepath.ToSlash(line))
		if path != "" {
			paths[path] = struct{}{}
		}
	}
	return paths
}

