def content_to_text(content):
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts=[]
        for item in content:
            if isinstance(item, dict):
                if 'text' in item and isinstance(item['text'], str): parts.append(item['text'])
                elif item.get('type') in ('input_text','output_text') and isinstance(item.get('text'), str): parts.append(item['text'])
        return '\n'.join(parts)
    return ''

def is_noise(text):
    t=text.strip()
    if not t: return True
    noise_prefixes=(
        '<local-command-caveat>', '<command-name>', '<local-command-stdout>', '<turn_aborted>',
        '# AGENTS.md instructions', '<environment_context>', '<permissions instructions>',
        '**ACTION REQUIRED: Spawn a subagent', 'Launching skill:',
    )
    if any(t.startswith(p) for p in noise_prefixes): return True
    if '<local-command-' in t[:200]: return True
    if 'tool_use_id' in t[:200] and 'tool_result' in t[:400]: return True
    return False

def extract_session(path):
    first_prompts=[]
    last_prompt=''
    title=''
    user_count=0
    assistant_count=0
    tool_names=collections.Counter()
    commands=collections.Counter()
    line_count=0
    try:
        with open(path, 'rb') as f:
            for raw in f:
                line_count+=1
                if line_count > 20000 and len(first_prompts) >= 3 and title and last_prompt:
                    # Enough for indexing; avoid spending too long on giant logs.
                    break
                try:
                    obj=json.loads(raw)
                except Exception:
                    continue
                typ=obj.get('type')
                if typ=='ai-title':
                    title=obj.get('aiTitle') or title
                if typ=='last-prompt':
                    last_prompt=obj.get('lastPrompt') or last_prompt
                # Claude raw format
                msg=obj.get('message')
                if isinstance(msg, dict):
                    role=msg.get('role')
                    if role=='user':
                        txt=content_to_text(msg.get('content'))
                        if not is_noise(txt):
                            user_count+=1
                            if len(first_prompts)<3:
                                first_prompts.append(txt.strip())
                    elif role=='assistant':
                        assistant_count+=1
                        cont=msg.get('content')
                        if isinstance(cont, list):
                            for item in cont:
                                if isinstance(item, dict) and item.get('type')=='tool_use':
                                    tool_names[item.get('name') or '<unknown>']+=1
                                    inp=item.get('input') or {}
                                    if isinstance(inp, dict) and item.get('name') in ('Bash','exec_command'):
                                        cmd=inp.get('command') or inp.get('cmd') or ''
                                        if cmd: commands[cmd.split()[0]]+=1
                # Codex raw format
                payload=obj.get('payload')
                if isinstance(payload, dict):
                    if payload.get('type')=='message':
                        role=payload.get('role')
                        cont=payload.get('content')
                        if role=='user':
