                            if not is_noise(txt):
                                user_count+=1
                                if len(first_prompts)<3:
                                    first_prompts.append(txt.strip())
                        elif role=='assistant':
                            assistant_count+=1
                    if payload.get('type')=='function_call':
                        name=payload.get('name') or '<unknown>'
                        tool_names[name]+=1
                        try:
                            args=json.loads(payload.get('arguments') or '{}')
