	if raw {
		return "raw"
	}
	return "compact"
}

func actualTranscriptMode(raw bool, snapshot *checkpointSnapshot) string {
	if snapshot != nil && snapshot.TranscriptMode != "" {
		return snapshot.TranscriptMode
