func exportRepoDir(env EntireEnv) (string, error) {
	if env.RepoRoot != "" {
		return env.RepoRoot, nil
	}
	wd, err := os.Getwd()
	if err != nil {
		return "", fmt.Errorf("get current directory: %w", err)
	}
