   381	func resolveDefaultBranchRef(ctx context.Context, runner CommandRunner, repoDir, defaultBranch string) (string, bool) {
   382		localRef := "refs/heads/" + defaultBranch
   383		if gitRefExists(ctx, runner, repoDir, localRef) {
